function polyEval(coeffs, x){ var r=0; for(var i=0;i<coeffs.length;i++){ r=r*x+coeffs[i]; } return r; } // coeffs highest degree first
function polyDeriv(coeffs){ var n=coeffs.length; if(n<2) return [0]; var d=[]; for(var i=0;i<n-1;i++){ var deg=n-1-i; d.push(coeffs[i]*deg); } return d; }
function numDeriv(f, x, h){ h=h||1e-7; return (f(x+h)-f(x-h))/(2*h); }
var EXPORTS = { polyEval:polyEval, polyDeriv:polyDeriv, numDeriv:numDeriv };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DerivativeForgePure = EXPORTS; }
